public class CF1342E_Variant4 {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        long k = Long.parseLong(parts[1]);

        if (k > n) {
            pw.println(0);
            pw.close();
            return;
        }

        int a = n - (int) k;
        long total = 0;
        long comb = 1;

        for (int i = a; i > 0; i--) {
            long sign = ((a - i) % 2 == 0) ? 1 : -1;
            total += sign * comb * fastPower(i, n);
            total %= 998244353;
            comb = (comb * i) % 998244353;
            comb = (comb * modInverse(a - i + 1, 998244353)) % 998244353;
        }

        int maxA = Math.max(a, (int) k);
        for (int i = maxA + 1; i <= n; i++) {
            total = (total * i) % 998244353;
        }

        for (int i = 1; i <= n - a; i++) {
            total = (total * modInverse(i, 998244353)) % 998244353;
        }

        if (k != 0) {
            total = (total * 2) % 998244353;
        }

        pw.println(total);
        pw.close();
    }

    private static long fastPower(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % 998244353;
            base = (base * base) % 998244353;
            exp >>= 1;
        }
        return result;
    }

    private static long modInverse(long a, int m) {
        return fastPower(a, m - 2);
    }
